package com.northstar.crm.service;

import com.northstar.crm.domain.*;import com.northstar.crm.repo.*;import com.northstar.crm.security.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.nio.charset.StandardCharsets;import java.security.*;import javax.crypto.SecretKeyFactory;import javax.crypto.spec.PBEKeySpec;import java.time.Instant;import java.util.*;import static com.northstar.crm.domain.DomainTypes.Role;
@Service public class AccountService {
 public record IssuedToken(String rawToken,Instant expiresAt){}
 private final UserRepository users;private final InviteRepository invites;private final PasswordResetRepository resets;private final OutboxRepository outbox;private final ActorResolver actors;private final AccessPolicy access;private final AuditService audit;private final PasswordEncoder passwords;private final OrganizationService organizations;private final String publicUrl;private final SecureRandom random=new SecureRandom();
 public AccountService(UserRepository u,InviteRepository i,PasswordResetRepository r,OutboxRepository o,ActorResolver a,AccessPolicy p,AuditService audit,PasswordEncoder passwords,OrganizationService organizations,@Value("${app.public-url}")String publicUrl){users=u;invites=i;resets=r;outbox=o;actors=a;access=p;this.audit=audit;this.passwords=passwords;this.organizations=organizations;this.publicUrl=publicUrl;}
 @Transactional(readOnly=true) public List<UserAccount> allUsers(){var actor=actors.current();access.requireAdmin(actor);return users.findAll().stream().sorted(Comparator.comparing(UserAccount::getDisplayName)).toList();}
 @Transactional public UserAccount updateProfile(String displayName){var actor=actors.current();if(displayName==null||displayName.isBlank()||displayName.length()>100)throw new IllegalArgumentException("Display name required");var before=actor.getDisplayName();actor.updateProfile(displayName.strip());audit.record(actor,"PROFILE_UPDATED","User",actor.getId(),"displayName="+before,"displayName="+actor.getDisplayName(),"self");return actor;}
 @Transactional public void setEnabled(UUID id,boolean enabled){var actor=actors.current();access.requireAdmin(actor);if(actor.getId().equals(id)&&!enabled)throw new IllegalArgumentException("You cannot disable your own account");var user=users.findById(id).orElseThrow();var before=user.isEnabled();user.setEnabled(enabled);audit.record(actor,enabled?"USER_ENABLED":"USER_DISABLED","User",id,"enabled="+before,"enabled="+enabled,"platform admin");}
 @Transactional public void changeRole(UUID id,Role role){var actor=actors.current();access.requireAdmin(actor);var user=users.findById(id).orElseThrow();if(user.getId().equals(actor.getId())&&role!=Role.PLATFORM_ADMIN)throw new IllegalArgumentException("You cannot remove your own admin role");var before=user.getRole();user.setRole(role);audit.record(actor,"USER_ROLE_CHANGED","User",id,"role="+before,"role="+role,"platform admin");}
 @Transactional public IssuedToken inviteCustomer(UUID organizationId,String email){var actor=actors.current();if(actor.getRole()!=Role.PLATFORM_ADMIN&&actor.getRole()!=Role.ACCOUNT_MANAGER)throw new AccessDeniedException("Account manager or admin required");access.requireManageOrganization(actor,organizations.getAuthorized(organizationId));if(email==null||!email.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$"))throw new IllegalArgumentException("Valid email required");if(users.findByEmailIgnoreCase(email).isPresent())throw new IllegalArgumentException("An account already exists");var raw=token();var expiry=Instant.now().plusSeconds(172800);var invite=invites.save(new InviteToken(hash(raw),email.toLowerCase(),organizationId,expiry));outbox.save(new OutboxMessage(email,"Your Northstar CRM invitation","Accept your invite: "+publicUrl+"/accept-invite?token="+raw));audit.record(actor,"CUSTOMER_INVITED","Invite",invite.getId(),"{}","email="+email+",organization="+organizationId,"verified organization owner or platform admin");return new IssuedToken(raw,expiry);}
 @Transactional public UserAccount acceptInvite(String raw,String name,String password){var token=invites.findByTokenHash(hash(raw)).orElseThrow(()->new IllegalArgumentException("Invite is invalid"));if(token.getUsedAt()!=null||token.getExpiresAt().isBefore(Instant.now()))throw new IllegalArgumentException("Invite has expired or was already used");validatePassword(password);var user=users.save(new UserAccount(token.getEmail(),name.strip(),passwords.encode(password),Role.CUSTOMER_CONTACT,token.getOrganizationId()));token.use();outbox.save(new OutboxMessage(user.getEmail(),"Welcome to Northstar CRM","Your portal account is ready."));audit.record(user,"INVITE_ACCEPTED","User",user.getId(),"{}","organization="+user.getOrganizationId(),"single-use time-bound invite");return user;}
 @Transactional public void requestPasswordReset(String email){
  var user=users.findByEmailIgnoreCase(Optional.ofNullable(email).orElse("")).filter(UserAccount::isEnabled)
   .orElseThrow(()->new IllegalArgumentException("No Northstar account is registered for that email"));
  var raw=token();resets.save(new PasswordResetToken(hash(raw),user.getId(),Instant.now().plusSeconds(3600)));
  outbox.save(new OutboxMessage(user.getEmail(),"Reset your Northstar password","Reset link: "+publicUrl+"/reset-password?token="+raw));
 }
 @Transactional public void resetPassword(String raw,String password){validatePassword(password);var reset=resets.findByTokenHash(hash(raw)).orElseThrow(()->new IllegalArgumentException("Reset link is invalid"));if(reset.getUsedAt()!=null||reset.getExpiresAt().isBefore(Instant.now()))throw new IllegalArgumentException("Reset link has expired or was already used");var user=users.findById(reset.getUserId()).orElseThrow();user.setPasswordHash(passwords.encode(password));reset.use();audit.record(user,"PASSWORD_RESET","User",user.getId(),"{}","password changed","single-use time-bound reset token");}
 @Transactional public void enrolDeskPassphrase(UUID id,String passphrase){var actor=actors.current();access.requireAdmin(actor);if(passphrase==null||passphrase.length()<6||passphrase.length()>128)throw new IllegalArgumentException("Passphrase must be 6–128 characters");var user=users.findById(id).orElseThrow();user.setDeskVerifier(deskDigest(passphrase));audit.record(actor,"DESK_PASSPHRASE_SET","User",id,"{}","verifier updated","platform admin");}
 @Transactional(readOnly=true) public boolean checkDeskPassphrase(String email,String passphrase){var user=users.findByEmailIgnoreCase(Optional.ofNullable(email).orElse("")).filter(UserAccount::isEnabled).orElseThrow(()->new IllegalArgumentException("No Northstar account is registered for that email"));if(user.getDeskVerifier()==null)throw new IllegalArgumentException("No desk passphrase is set for this account");return MessageDigest.isEqual(deskDigest(passphrase).getBytes(StandardCharsets.UTF_8),user.getDeskVerifier().getBytes(StandardCharsets.UTF_8));}
 private String deskDigest(String passphrase){try{var spec=new PBEKeySpec(passphrase.toCharArray(),"northstar-desk".getBytes(StandardCharsets.UTF_8),1024,128);return HexFormat.of().formatHex(SecretKeyFactory.getInstance("PBKDF2WithHmacSHA1").generateSecret(spec).getEncoded());}catch(GeneralSecurityException e){throw new IllegalStateException(e);}}
 private void validatePassword(String p){if(p==null||p.length()<12||p.length()>128||!p.matches(".*[A-Z].*")||!p.matches(".*[a-z].*")||!p.matches(".*[0-9].*"))throw new IllegalArgumentException("Use 12–128 characters with upper, lower, and number");}
 private String token(){var bytes=new byte[32];random.nextBytes(bytes);return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);}private String hash(String raw){if(raw==null||raw.length()>200)throw new IllegalArgumentException("Invalid token");try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
